from functools import lru_cache
cells={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# candidates tile shape naming; coordinates top-left in 2x2
shapes={1:{(0,0),(0,1),(1,0),(1,1)},2:{(0,1),(1,0),(1,1)},3:{(0,0),(0,1),(1,1)},4:{(0,0),(1,0),(1,1)}}
opts=[]
for color,shape in shapes.items():
  for r in range(4):
    for c in range(6):
      tile={(r+dr,c+dc) for dr,dc in shape}
      if tile<=cells: opts.append((color,tile))
bycell={p:[] for p in cells}
for o in opts:
  for p in o[1]: bycell[p].append(o)
sol=[]
def go(rem,chosen):
 if not rem:
  sol.append(chosen); return
 p=min(rem,key=lambda x:sum(t<=rem for _,t in bycell[x]))
 for col,t in bycell[p]:
  if t<=rem: go(rem-t,chosen+[(col,t)])
go(cells,[])
print('solutions',len(sol))
for s in sol[:10]:
 print([(co,sorted(t)) for co,t in s])
